def main():
    assert len(RAW_ITEMS) == 200, f"Expected 200 items, got {len(RAW_ITEMS)}"

    # Load existing JS file
    txt = CA_JS_PATH.read_text(encoding="utf-8")
    m = re.search(r"window\.CURRENT_AFFAIRS_200_MCQS\s*=\s*(\[.*\]);?\s*$", txt, flags=re.S)
    if not m:
        raise RuntimeError("Could not parse window.CURRENT_AFFAIRS_200_MCQS from data_current_affairs_200.js")

    existing = json.loads(m.group(1).rstrip(";").strip())
    # Make script idempotent: keep only original first 200 items (ca_ext_1 .. ca_ext_200) before appending
    base_200 = [q for q in existing if int(str(q.get("_id", "ca_ext_0")).split("_")[-1]) <= 200]
    assert len(base_200) == 200, f"Expected 200 base items, found {len(base_200)}"

    letters = ["A", "B", "C", "D"]
    new_mcqs = []

    for idx, (sub_cat, diff, q_text, correct_txt, distractors, exp) in enumerate(RAW_ITEMS):
        q_num = 201 + idx
        # Deterministic rotation across A, B, C, D (50 each!)
        target_pos = idx % 4
        target_letter = letters[target_pos]

        # Arrange options so correct_txt sits at target_pos
        d = list(distractors)
        ordered = []
        d_i = 0
        for pos in range(4):
            if pos == target_pos:
                ordered.append(correct_txt)
            else:
                ordered.append(d[d_i])
                d_i += 1

        opts = {letters[i]: ordered[i] for i in range(4)}
        new_mcqs.append({
            "_id": f"ca_ext_{q_num}",
            "questionId": q_num,
            "questionText": q_text,
            "options": opts,
            "correctAnswer": target_letter,
            "correctAnswerText": correct_txt,
            "explanation": exp,
            "category": {
                "_id": "cat_ca",
                "name": "Current Affairs"
            },
            "subCategory": sub_cat,
            "difficulty": diff,
            "source": "Competitive Exams Current Affairs — International, Regional & Pakistan (2024-2026)"
        })

    combined = base_200 + new_mcqs
    json_str = json.dumps(combined, ensure_ascii=False, indent=2)

    header = (
        "/**\n"
        " * 400 High-Yield Current Affairs MCQs (2024–2026)\n"
        " * - Pakistan Current Affairs (168 MCQs)\n"
        " * - Regional Current Affairs — South Asia, Middle East & Central Asia (66 MCQs)\n"
        " * - International Current Affairs (166 MCQs)\n"
        " */\n"
        "window.CURRENT_AFFAIRS_200_MCQS = "
    )
    CA_JS_PATH.write_text(header + json_str + ";\n", encoding="utf-8")
    CA_JSON_PATH.write_text(json_str + "\n", encoding="utf-8")

    # Summary stats
    from collections import Counter
    sub_counts = Counter(q["subCategory"] for q in new_mcqs)
    ans_counts = Counter(q["correctAnswer"] for q in new_mcqs)
    print(f"Successfully wrote {len(combined)} total MCQs ({len(new_mcqs)} newly added: ca_ext_201..ca_ext_400).")
    print("New 200 SubCategory breakdown:", dict(sub_counts))
    print("New 200 CorrectAnswer balance:", dict(ans_counts))


if __name__ == "__main__":
    main()
